-- Seeds tab 3 ("Best Soundtrack Jams"): introduces production_types and
-- productions, links each song to the production(s) it appeared in via
-- song_productions, and seeds the list itself the same way tab 2 did. Every
-- production defaults to the "Film" type for now, per product decision - a
-- later pass will correct the handful that are actually Television or
-- Stage. Release years were filled in from general knowledge, not the
-- sheet, since the schema requires one; worth a spot check.





UPDATE "song_lists"."songs" SET "bio" = trim(both ' ' from coalesce("bio", '') || ' ' || 'You gonna go race Notcher in your Cessna?') WHERE "artist_id" = (SELECT "id" FROM "song_lists"."artists" WHERE "name" = 'Adrenalin') AND "title" = 'Road Of The Gypsy';
UPDATE "song_lists"."songs" SET "bio" = trim(both ' ' from coalesce("bio", '') || ' ' || 'Talk Hard!') WHERE "artist_id" = (SELECT "id" FROM "song_lists"."artists" WHERE "name" = 'Leonard Cohen') AND "title" = 'Everybody Knows';
UPDATE "song_lists"."songs" SET "bio" = trim(both ' ' from coalesce("bio", '') || ' ' || 'This shit right here will make you a certified lady killer!') WHERE "artist_id" = (SELECT "id" FROM "song_lists"."artists" WHERE "name" = 'Little Richard') AND "title" = 'Long Tall Sally';



